etl.script:
create table t (
id int,
c varbinary
);
insert into t(id, c) values(1,?{file 'tst://file'});
insert into t(id, c) values(2,?{file 'tst://file'});
insert into t(id, c) values(3,?{file 'tst://file'})

create table txt (
id int,
c longvarchar
);
insert into txt(id, c) values(1,?{textfile 'tst://file'});
